from fractions import Fraction

def hit_prob(n):
    """Exact chance a fair +-1 walk from 0 has reached +1 within n steps."""
    dist = {0: Fraction(1)}   # chance of being at each position, not yet hit
    hit = Fraction(0)
    for _ in range(n):
        new = {}
        for pos, p in dist.items():
            for step in (1, -1):
                q = pos + step
                if q == 1:
                    hit += p / 2
                else:
                    new[q] = new.get(q, 0) + p / 2
        dist = new
    return hit
